param([string]$Active=$env:EB_BLUE_ENV,[string]$Previous=$env:EB_GREEN_ENV)$ErrorActionPreference="Stop";if(-not $env:AWS_REGION -or -not $Active -or -not $Previous){throw "AWS_REGION and both Elastic Beanstalk environment names are required"};aws elasticbeanstalk swap-environment-cnames --region $env:AWS_REGION --source-environment-name $Active --destination-environment-name $Previous
